    if all(len(set(row)) == 1 for row in grid):
        known = [(i, row[0]) for i, row in enumerate(grid) if row[0] != 0]
        period = len(known)
        if not period:
            return [row[:] for row in grid]
        pattern = {}
        for i, color in known:
            r = i % period
            if r in pattern and pattern[r] != color:
                raise ValueError('inconsistent row pattern')
            pattern[r] = color
        return [[pattern[i % period]] * w for i in range(h)]
    for period in range(1, max(h, w) + 1):
        pattern = {}
        valid = True
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
